    /// AC-001: two distinct packages declaring the same triple must get
    /// distinct artifactName values, each embedding that package's own
    /// name, so callisto-action's unique_by(.artifactName) dedup (AC-002)
    /// does not collapse them.
    #[test]
    fn build_matrix_report_same_triple_two_packages_have_distinct_artifact_names() {
        let tmp = tempfile::tempdir().unwrap();
        for name in ["pkg-a", "pkg-b"] {
            let dir = tmp.path().join(name);
            std::fs::create_dir_all(&dir).unwrap();
            std::fs::write(
                dir.join("package.json"),
                r#"{"napi":{"targets":["x86_64-apple-darwin"]}}"#,
            )
            .unwrap();
        }
        let inputs = vec![
            input("pkg-a", &tmp.path().join("pkg-a")),
            input("pkg-b", &tmp.path().join("pkg-b")),
        ];
        let report = build_matrix_report(&inputs).unwrap();

        let a_name = &report.platform_targets["pkg-a"].targets[0].artifact_name;
        let b_name = &report.platform_targets["pkg-b"].targets[0].artifact_name;

        assert_eq!(a_name, "native-pkg-a-x86_64-apple-darwin");
        assert_eq!(b_name, "native-pkg-b-x86_64-apple-darwin");
        assert_ne!(a_name, b_name);
    }

